import pathlib,json,numpy as np,hashlib
b=pathlib.Path(__file__).parent.parent; out={}
for p in sorted(b.glob('*/measurements.json')):
 m=json.load(open(p)); ev=[e for e in m['events'] if e.get('timing_usable') and ('orbital_cycle' in e if m['tic']=='403154475' else True)];n=np.array([e.get('orbital_cycle',e['cycle']) for e in ev]);t=np.array([e['mid_btjd'] for e in ev]);err=np.array([e['timing_error_days'] for e in ev]);X=np.column_stack([np.ones(len(n)),n-n.min()]);A=X/err[:,None];y=t/err;beta=np.linalg.lstsq(A,y,rcond=None)[0]; residual=t-X@beta;red=np.sum((residual/err)**2)/max(len(n)-2,1);cov=np.linalg.inv(A.T@A)*max(1,red);result={'count':len(n),'selection':[[e['sector'],e['cycle']] for e in ev],'excluded_numerical':[[e.get('sector'),e.get('cycle'),e.get('timing_failure_reason',e.get('error'))] for e in m['events'] if not e.get('timing_usable')], 'period':float(beta[1]),'epoch':float(beta[0]),'period_error':float(np.sqrt(cov[1,1])),'d_period':float(beta[1]-m['period_days']),'d_epoch':float(beta[0]-m['primary_epoch_btjd']),'d_error':float(np.sqrt(cov[1,1])-m['period_error_days']),'measurements_sha256':hashlib.sha256(p.read_bytes()).hexdigest()};out[m['tic']]=result;print(m['tic'],len(n),result['excluded_numerical'],result['d_period'],result['d_epoch'],result['d_error'])
json.dump(out,open(b/'helper/regression-audit.json','w'),indent=2)
